  "node:os":            path.join(SHIMS, "node-os.ts"),
  "os":                 path.join(SHIMS, "node-os.ts"),
},
plugins: [
  // esbuild alias only supports bare module names; use a plugin to intercept
  // the absolute path of server/src/middleware/logger.ts → CF-safe shim.
  {
    name: "server-logger-shim",
    setup(build) {
      const loggerReal = path.resolve(__dirname, "../../server/src/middleware/logger.ts");
      const loggerShim = path.join(SHIMS, "server-logger-shim.ts");
      build.onResolve({ filter: /logger/ }, (args) => {
        const resolved = path.resolve(args.resolveDir, args.path);
        if (resolved === loggerReal || resolved === loggerReal.replace(/\.ts$/, ".js")) {
          return { path: loggerShim };
        }
      });
    },
  },
],
